-- =====================================================================
-- DATABASE BIOSKOP (versi diperbanyak) - Group Assignment #1 SMBD
-- Referensi struktur: database_bioskop.sql (bioskop_vvi)
-- Jumlah data  : Film 3000 | Pelanggan 3500 | JadwalTayang 3000 | Transaksi 6000
-- Tabel master : Cabang, MetodeBayar, Film, Pelanggan, JadwalTayang
-- Tabel transaksi : Transaksi
-- =====================================================================
/*CREATE DATABASE IF NOT EXISTS bioskop_smbd;
USE bioskop_smbd;
*/
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS Transaksi;
DROP TABLE IF EXISTS JadwalTayang;
DROP TABLE IF EXISTS Pelanggan;
DROP TABLE IF EXISTS Film;
DROP TABLE IF EXISTS MetodeBayar;
DROP TABLE IF EXISTS Cabang;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------- TABEL MASTER ----------------
CREATE TABLE Cabang (
    id_cabang   VARCHAR(10) PRIMARY KEY,
    nama_cabang VARCHAR(100) NOT NULL,
    alamat      VARCHAR(150),
    kota        VARCHAR(50)
);

CREATE TABLE MetodeBayar (
    id_metodeBayar   VARCHAR(10) PRIMARY KEY,
    nama_metodeBayar VARCHAR(50) NOT NULL,
    diskon           INT NOT NULL DEFAULT 0
);

CREATE TABLE Film (
    id_film     VARCHAR(10) PRIMARY KEY,
    judul       VARCHAR(150) NOT NULL,
    genre       VARCHAR(30),
    durasi      INT,                 -- dalam menit
    rating      VARCHAR(10),         -- SU / 13+ / 17+ / 21+
    tahun_rilis INT,
    skor        DECIMAL(2,1)
);

CREATE TABLE Pelanggan (
    id_pelanggan       VARCHAR(10) PRIMARY KEY,
    nama               VARCHAR(100) NOT NULL,
    email              VARCHAR(100) NOT NULL,
    no_telp            VARCHAR(20),
    kota               VARCHAR(50),
    tanggal_lahir      DATE,
    status_keanggotaan VARCHAR(20),
    tanggal_daftar     DATE
);

CREATE TABLE JadwalTayang (
    id_jadwal  VARCHAR(10) PRIMARY KEY,
    id_film    VARCHAR(10) NOT NULL,
    id_cabang  VARCHAR(10) NOT NULL,
    studio     INT,
    tanggal    DATE NOT NULL,
    jam_mulai  TIME NOT NULL,
    format     VARCHAR(10),
    harga      INT NOT NULL,
    FOREIGN KEY (id_film)   REFERENCES Film(id_film),
    FOREIGN KEY (id_cabang) REFERENCES Cabang(id_cabang)
);

-- ---------------- TABEL TRANSAKSI ----------------
CREATE TABLE Transaksi (
    id_transaksi   VARCHAR(10) PRIMARY KEY,
    id_pelanggan   VARCHAR(10) NOT NULL,
    id_jadwal      VARCHAR(10) NOT NULL,
    id_metodeBayar VARCHAR(10) NOT NULL,
    jumlah_tiket   INT NOT NULL,
    total          INT NOT NULL,
    tanggal        DATE NOT NULL,
    waktu          TIME NOT NULL,
    status         VARCHAR(20),
    FOREIGN KEY (id_pelanggan)   REFERENCES Pelanggan(id_pelanggan),
    FOREIGN KEY (id_jadwal)      REFERENCES JadwalTayang(id_jadwal),
    FOREIGN KEY (id_metodeBayar) REFERENCES MetodeBayar(id_metodeBayar)
);

